#include <Arduino.h>
#include "pins.h"
#include <SPI.h>
#include <ld2410.h>
#include <TFT_eSPI.h>


void setup() {
  Serial.begin(115200);
  SPI.begin(SPI0_SCK, SPI0_MISO, SPI0_MOSI);
  Serial1.begin(256000, SERIAL_8N1, UART0_RX, UART0_TX);
  pinMode(PRESENCE_RADAR_OUT, OUTPUT);
  pinMode(DISPLAY_CS, OUTPUT);
  pinMode(DISPLAY_DC, OUTPUT);
  pinMode(DISPLAY_LED, OUTPUT);
  pinMode(DISPLAY_RST, OUTPUT);
  pinMode(DISPLAY_T_CS, OUTPUT);
  pinMode(DISPLAY_T_IRQ, OUTPUT);
  Serial.println("boot ok");
}

void loop() {
  delay(1000);
}
